use crate::{ciphertext_commitment, encrypt_note, kdf_to_aes_key_iv, Note, pack_ciphertext};
use dep::poseidon::poseidon2::Poseidon2;

// Verifies ownership, enforces timelocks/hashlocks, and derives the correct nullifier.
// Returns (Nullifier, Commitment) to the caller.
pub fn verify_spend(
    note: Note,
    shared_secret: Field,
    note_index: Field,
    current_timestamp: Field,
    hashlock_preimage: Field,
) -> (Field, Field) {
    // 1. Verify Decryption (Proof of Ownership)
    // Re-encrypt the note to ensure the provided 'shared_secret' matches the note data.
    let (key, iv) = kdf_to_aes_key_iv(shared_secret);
    let plaintext = note.serialize();
    let ciphertext = encrypt_note(plaintext, iv, key);
    let packed = pack_ciphertext(ciphertext);
    let commitment = ciphertext_commitment(packed);

    // 2. Enforce Programmability
    // Timelock: If set (>0), current time must be >= timelock
    if note.timelock != 0 {
        assert(current_timestamp as u64 >= note.timelock as u64);
    }

    // Hashlock: If set (!=0), hash(preimage) must match hashlock
    if note.hashlock != 0 {
        let derived_hash = Poseidon2::hash([hashlock_preimage], 1);
        assert(derived_hash == note.hashlock);
    }

    // 3. Derive Nullifier (Dual-Path Logic)
    let nullifier = if note.nullifier == 0 {
        // Path B: Transfer Note (Received from someone else)
        // Since `note.nullifier` is empty, we must derive a deterministic nullifier
        // based on the shared secret (known to sender) and position.
        Poseidon2::hash([shared_secret, commitment, note_index], 3)
    } else {
        // Path A: Self Note (Deposit/Change)
        // User generated a random nullifier secret.
        Poseidon2::hash([note.nullifier], 1)
    };

    (nullifier, commitment)
}

